/*
 * docker-logconfig.js translates the docker json-file log options stored
 * in the 'docker:logconfig' internal_metadata key into the zoneadmd(8) log
 * rotation settings used by vmadm (zlog_max_size, zlog_keep_rotated).
 *
 * The input is user-controlled, so nothing here throws: invalid options
 * are reported in 'errors' and simply produce no setting.
 */

var assert = require('/usr/node/node_modules/assert-plus');

/* Largest integer a JS Number holds exactly (Number.MAX_SAFE_INTEGER). */
var MAX_SAFE_INTEGER = 9007199254740991;

/* zoneadmd keeps at most this many rotated logs (ZLOG_KEEP_MAX). */
var ZLOG_KEEP_MAX = 1000;

/* docker max-size: positive integer with optional k/m/g (powers of 1000) */
var MAX_SIZE_RE = /^([1-9][0-9]{0,14})([kmg]?)$/;
var MAX_SIZE_MULTIPLIER = {'': 1, k: 1000, m: 1000000, g: 1000000000};

/* docker max-file: positive integer */
var MAX_FILE_RE = /^[1-9][0-9]{0,8}$/;

/**
 * Returns the option value as a string if it is a string or a number,
 * otherwise undefined.
 *
 * @param {*} value - raw option value from the parsed logconfig
 * @returns {String|undefined}
 */
function optString(value) {
    if (typeof (value) === 'string' || typeof (value) === 'number') {
        return String(value);
    }
    return undefined;
}

/**
 * Converts a docker max-size value to bytes.
 *
 * @param {String} value - e.g. '30m', '1000', '2g'
 * @returns {Number|undefined} bytes, or undefined if invalid or too large
 */
function maxSizeToBytes(value) {
    var m = MAX_SIZE_RE.exec(value);
    var bytes;

    if (m === null) {
        return undefined;
    }

    bytes = Number(m[1]) * MAX_SIZE_MULTIPLIER[m[2]];
    if (bytes > MAX_SAFE_INTEGER) {
        return undefined;
    }

    return bytes;
}

/**
 * Converts a docker max-file value to a zoneadmd rotated-log count.
 *
 * docker's max-file counts the live log, zoneadmd counts only rotated
 * logs, so keep = max-file - 1. zoneadmd treats 0 as "keep all", so the
 * result is never below 1 (max-file=1 keeps one rotated log) and never
 * above ZLOG_KEEP_MAX.
 *
 * @param {String} value - e.g. '3'
 * @returns {Number|undefined} count in [1, 1000], or undefined if invalid
 */
function maxFileToKeep(value) {
    if (!MAX_FILE_RE.test(value)) {
        return undefined;
    }

    return Math.min(ZLOG_KEEP_MAX, Math.max(1, Number(value) - 1));
}

/**
 * Translates a 'docker:logconfig' JSON string into zlog settings.
 *
 * @param {String} logconfig - JSON object string, e.g.
 *     '{"max-file":"3","max-size":"30m"}'
 * @returns {Object} result
 * @returns {Number} [result.zlog_max_size] - from max-size, in bytes
 * @returns {Number} [result.zlog_keep_rotated] - from max-file
 * @returns {String[]} result.errors - one message per ignored option
 */
function zlogFromLogConfig(logconfig) {
    var cfg;
    var keep;
    var result = {errors: []};
    var size;
    var value;

    assert.string(logconfig, 'logconfig');

    try {
        cfg = JSON.parse(logconfig);
    } catch (e) {
        result.errors.push('docker:logconfig is not valid JSON');
        return result;
    }

    if (cfg === null || typeof (cfg) !== 'object' || Array.isArray(cfg)) {
        result.errors.push('docker:logconfig is not a JSON object');
        return result;
    }

    if (cfg.hasOwnProperty('max-size')) {
        value = optString(cfg['max-size']);
        size = (value === undefined) ? undefined : maxSizeToBytes(value);
        if (size === undefined) {
            result.errors.push('invalid max-size in docker:logconfig');
        } else {
            result.zlog_max_size = size;
        }
    }

    if (cfg.hasOwnProperty('max-file')) {
        value = optString(cfg['max-file']);
        keep = (value === undefined) ? undefined : maxFileToKeep(value);
        if (keep === undefined) {
            result.errors.push('invalid max-file in docker:logconfig');
        } else {
            result.zlog_keep_rotated = keep;
        }
    }

    return result;
}

module.exports = {
    zlogFromLogConfig: zlogFromLogConfig
};
